    def __init__(self, root):
        self.values = []
        def inorder(node):
            if node:
                inorder(node.left); self.values.append(node.val); inorder(node.right)
        inorder(root)                              # full traversal upfront, O(n) space
        self.index = 0

    def next(self):
        val = self.values[self.index]
        self.index += 1
        return val

    def has_next(self):
        return self.index < len(self.values)

