class BSTIterator:
    def __init__(self, root):
        self.stack = []
        self._push_left(root)

    def _push_left(self, node):
        while node:
            self.stack.append(node)                  # push the entire left spine
            node = node.left

    def next(self):
        node = self.stack.pop()
        self._push_left(node.right)                    # lazily expand the right child's left spine
        return node.val

    def has_next(self):
        return len(self.stack) > 0

