import java.util.*;

class BSTIterator {
    Deque<TreeNode> stack = new ArrayDeque<>();

    BSTIterator(TreeNode root) {
        pushLeft(root);
    }

    void pushLeft(TreeNode node) {
        while (node != null) {
            stack.push(node);                             // push the entire left spine
            node = node.left;
        }
    }

    int next() {
        TreeNode node = stack.pop();
        pushLeft(node.right);                                // lazily expand the right child's left spine
        return node.val;
    }

    boolean hasNext() {
        return !stack.isEmpty();
    }
}

