class BSTIterator {
public:
    stack<TreeNode*> st;

    BSTIterator(TreeNode* root) {
        pushLeft(root);
    }

    void pushLeft(TreeNode* node) {
        while (node) {
            st.push(node);                                    // push the entire left spine
            node = node->left;
        }
    }

    int next() {
        TreeNode* node = st.top(); st.pop();
        pushLeft(node->right);                                  // lazily expand the right child's left spine
        return node->val;
    }

    bool hasNext() {
        return !st.empty();
    }
};
